"use strict";(self.webpackChunktouchgfx_documentation=self.webpackChunktouchgfx_documentation||[]).push([[99151],{11114:t=>{t.exports=JSON.parse('{"pluginId":"academy","version":"current","label":"\ub2e4\uc74c","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"academy":[{"type":"link","label":"\uc11c\ub860","href":"/4.27/ko/academy/academy-introduction","docId":"academy-introduction"},{"label":"\uc790\uc2b5\uc11c","type":"category","items":[{"type":"link","label":"Tutorial 1: Trying Out the Examples","href":"/4.27/ko/academy/tutorials/tutorial-01","docId":"tutorials/tutorial-01"},{"type":"link","label":"Tutorial 2: Creating Your Own Application","href":"/4.27/ko/academy/tutorials/tutorial-02","docId":"tutorials/tutorial-02"},{"type":"link","label":"Tutorial 3: Applications with Multiple Screens","href":"/4.27/ko/academy/tutorials/tutorial-03","docId":"tutorials/tutorial-03"},{"type":"link","label":"Tutorial 4: Creating a Scroll Wheel with Custom Behavior","href":"/4.27/ko/academy/tutorials/tutorial-04","docId":"tutorials/tutorial-04"},{"type":"link","label":"Tutorial 5: Creating Custom Triggers and Actions","href":"/4.27/ko/academy/tutorials/tutorial-05","docId":"tutorials/tutorial-05"},{"label":"\uc790\uc2b5\uc11c 6: TextArea \uc0ac\uc6a9\ud558\uae30","type":"category","items":[{"type":"link","label":"Part 1 \u2013 Typography and Language","href":"/4.27/ko/academy/tutorials/tutorial-06/tutorial-06-part-1","docId":"tutorials/tutorial-06/tutorial-06-part-1"},{"type":"link","label":"Part 2 \u2013 Appearance of TextArea and Wildcard","href":"/4.27/ko/academy/tutorials/tutorial-06/tutorial-06-part-2","docId":"tutorials/tutorial-06/tutorial-06-part-2"}],"collapsed":true,"collapsible":true,"href":"/4.27/ko/academy/tutorials/tutorial-06/tutorial-06-introduction"}],"collapsed":true,"collapsible":true,"href":"/4.27/ko/academy/category/tutorials"},{"label":"Board Tutorials","type":"category","items":[{"type":"link","label":"Creating an Application for the TSD Knob Display","href":"/4.27/ko/academy/board-tutorials/tsd-knob-display","docId":"board-tutorials/tsd-knob-display"},{"type":"link","label":"Creating an Application for NUCLEO-C5A3ZG + RVA15MD","href":"/4.27/ko/academy/board-tutorials/nucleo-c5a3zg-rva15md","docId":"board-tutorials/nucleo-c5a3zg-rva15md"}],"collapsed":true,"collapsible":true,"href":"/4.27/ko/academy/category/board-tutorials"},{"label":"\\"TouchGFX \uc0ac\uc6a9 \ubc29\ubc95\\" \ube44\ub514\uc624","type":"category","items":[{"type":"link","label":"TouchGFX \uc124\uce58","href":"/4.27/ko/academy/how-to/install-touchgfx","docId":"how-to/install-touchgfx"},{"type":"link","label":"\ub0b4 \uccab GUI","href":"/4.27/ko/academy/how-to/my-first-gui","docId":"how-to/my-first-gui"},{"type":"link","label":"\ud074\ub9ad \uac00\ub2a5 \uc601\uc5ed \ub9cc\ub4e4\uae30","href":"/4.27/ko/academy/how-to/create-a-clickable-area","docId":"how-to/create-a-clickable-area"},{"type":"link","label":"\uc704\uc82f\uc758 \uc774\ub3d9 \ubc0f \uc560\ub2c8\uba54\uc774\uc158 \uc801\uc6a9","href":"/4.27/ko/academy/how-to/move-and-animate-widget","docId":"how-to/move-and-animate-widget"},{"type":"link","label":"Fade \uc704\uc82f","href":"/4.27/ko/academy/how-to/fade-widget","docId":"how-to/fade-widget"},{"type":"link","label":"\uc2a4\ud06c\ub9b0 \uc804\ud658","href":"/4.27/ko/academy/how-to/screen-transition","docId":"how-to/screen-transition"},{"type":"link","label":"\ub7f0\ud0c0\uc784 \uc2dc \ud14d\uc2a4\ud2b8 \ubcc0\uacbd","href":"/4.27/ko/academy/how-to/textarea","docId":"how-to/textarea"},{"type":"link","label":"\uc774\ubbf8\uc9c0 \ucd94\uac00","href":"/4.27/ko/academy/how-to/images","docId":"how-to/images"},{"type":"link","label":"\ucee4\uc2a4\ud140 \ucee8\ud14c\uc774\ub108 \uc0dd\uc131","href":"/4.27/ko/academy/how-to/custom-container","docId":"how-to/custom-container"},{"type":"link","label":"\uc801\uc808\ud55c \ud504\ub808\uc784 \ubc84\ud37c \uc804\ub7b5 \uc120\ud0dd","href":"/4.27/ko/academy/how-to/framebuffer-strategies","docId":"how-to/framebuffer-strategies"},{"type":"link","label":"\uc5d0\ubbac\ub808\uc774\uc158 \ud504\ub808\uc784 \ubc84\ud37c\uc758 \uad6c\ud604","href":"/4.27/ko/academy/how-to/emulated-framebuffer","docId":"how-to/emulated-framebuffer"},{"type":"link","label":"\ub2e8\uc77c \ud504\ub808\uc784 \ubc84\ud37c\uc758 \uad6c\ud604","href":"/4.27/ko/academy/how-to/single-framebuffer","docId":"how-to/single-framebuffer"},{"type":"link","label":"\ud50c\ub798\uc2dc \uba54\ubaa8\ub9ac \uc808\uc57d","href":"/4.27/ko/academy/how-to/save-flash-memory","docId":"how-to/save-flash-memory"}],"collapsed":true,"collapsible":true,"href":"/4.27/ko/academy/how-to/how-to-introduction"}]},"docs":{"academy-introduction":{"id":"academy-introduction","title":"\uc11c\ub860","description":"TouchGFX \uc544\uce74\ub370\ubbf8\uc5d0 \uc624\uc2e0 \uac83\uc744 \ud658\uc601\ud569\ub2c8\ub2e4!","sidebar":"academy"},"board-tutorials/nucleo-c5a3zg-rva15md":{"id":"board-tutorials/nucleo-c5a3zg-rva15md","title":"Creating an Application for NUCLEO-C5A3ZG + RVA15MD","description":"In this tutorial, we will create a simple GUI application using the basic features of TouchGFX. We will target the application for the \\"NUCLEO-C5A3ZG + RVA15MD\\" platform, which has the following specifications:","sidebar":"academy"},"board-tutorials/tsd-knob-display":{"id":"board-tutorials/tsd-knob-display","title":"Creating an Application for the TSD Knob Display","description":"In this tutorial, we will create and load an application for the TSD TSS013004A-AD display knob module. This is a graphics entry-level 1.3\u201d round display module based on STM32C091 + 8 MB external flash, running partial framebuffer. The application will have a simple GUI and show how to use the interfaces of the display module (physical controls, ambient light, and UART communication). The MCU platform in the TSD TSS013004A-AD display knob module has the following specifications:","sidebar":"academy"},"how-to/create-a-clickable-area":{"id":"how-to/create-a-clickable-area","title":"\ud074\ub9ad \uac00\ub2a5 \uc601\uc5ed \ub9cc\ub4e4\uae30","description":"\uc774 \ube44\ub514\uc624\ub294 \uc0ac\uc6a9\uc790 \uc778\ud130\ub799\uc158 \ubc0f \uacbd\ud5d8 \ud5a5\uc0c1\uc5d0 \uc911\uc694\ud55c \uae30\ub2a5\uc778 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ud074\ub9ad \uac00\ub2a5 \uc601\uc5ed\uc744 \ub9cc\ub4dc\ub294 \ubc95\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.","sidebar":"academy"},"how-to/custom-container":{"id":"how-to/custom-container","title":"\ucee4\uc2a4\ud140 \ucee8\ud14c\uc774\ub108 \uc0dd\uc131","description":"\ucee4\uc2a4\ud140 \ucee8\ud14c\uc774\ub108\ub97c \uc0ac\uc6a9\ud558\uba74 \uc704\uc82f \uac04\uc5d0 \uace0\uc720\ud55c \uc0c1\ud638\uc791\uc6a9\uc744 \ub9cc\ub4e4\uc5b4 \ud2b9\uc815\ud55c \ub3d9\uc791\uc744 \ub2ec\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ucee8\ud14c\uc774\ub108\ub97c \ub0b4\ubcf4\ub0b4\uace0 \uac00\uc838\uc62c \uc218 \uc788\ub2e4\uba74, \ub2e4\uc591\ud55c \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \ub514\uc790\uc778\uc744 \uc190\uc27d\uac8c \uc7ac\uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","sidebar":"academy"},"how-to/emulated-framebuffer":{"id":"how-to/emulated-framebuffer","title":"\uc5d0\ubbac\ub808\uc774\uc158 \ud504\ub808\uc784 \ubc84\ud37c\uc758 \uad6c\ud604","description":"\uc774 \ube44\ub514\uc624\uc5d0\uc11c\ub294 \uc5d0\ubbac\ub808\uc774\uc158 \ud504\ub808\uc784 \ubc84\ud37c \uc804\ub7b5\uc744 \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uc608\uc81c\ub294 STM32H7S78-DK\ub97c \uae30\ubc18\uc73c\ub85c \ud558\uc9c0\ub9cc, \ub3d9\uc77c\ud55c \uc808\ucc28\uac00 \uc5d0\ubbac\ub808\uc774\uc158 \ud504\ub808\uc784 \ubc84\ud37c\ub97c \uc9c0\uc6d0\ud558\ub294 \ub2e4\ub978 \ubcf4\ub4dc\uc5d0\ub3c4 \uc801\uc6a9\ub429\ub2c8\ub2e4.","sidebar":"academy"},"how-to/fade-widget":{"id":"how-to/fade-widget","title":"Fade \uc704\uc82f","description":"\uc704\uc82f\uc744 \ud398\uc774\ub4dc\ud558\ub294 \ubc29\ubc95\uc744 \uc644\ubcbd\ud788 \uc775\ud600 \uc0ac\uc6a9\uc790 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uac1c\uc120\ud558\ub294 \ubc95\uc744 \uc54c\uc544\ubcf4\uc2ed\uc2dc\uc624. \uc774 \ud29c\ud1a0\ub9ac\uc5bc\uc740 TouchGFX\uc5d0\uc11c \uc704\uc82f\uc744 \ud398\uc774\ub4dc\ud558\ub294 \ub2e4\uc74c \uc138 \uac00\uc9c0 \ubc29\ubc95\uc744 \ud65c\uc6a9\ud558\uc5ec \uc2dc\uc120\uc744 \uc0ac\ub85c\uc7a1\ub294 \uadf8\ub798\ud53d \uc0ac\uc6a9\uc790 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uc81c\uc791\ud558\ub294 \ubc95\uc744 \uc548\ub0b4\ud569\ub2c8\ub2e4.","sidebar":"academy"},"how-to/framebuffer-strategies":{"id":"how-to/framebuffer-strategies","title":"\uc801\uc808\ud55c \ud504\ub808\uc784 \ubc84\ud37c \uc804\ub7b5 \uc120\ud0dd","description":"\uc774 \ube44\ub514\uc624\uc5d0\uc11c\ub294 TouchGFX\uc758 \ud504\ub808\uc784 \ubc84\ud37c \uac1c\ub150\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. \uc801\uc808\ud55c \ud504\ub808\uc784 \ubc84\ud37c \uc804\ub7b5\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc740 \uba54\ubaa8\ub9ac \ub808\uc774\uc544\uc6c3\uc744 \ucd5c\uc801\ud654\ud558\uace0 \ud558\ub4dc\uc6e8\uc5b4\uc5d0\uc11c \uc131\ub2a5\uc744 \uadf9\ub300\ud654\ud558\ub294 \ub370 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","sidebar":"academy"},"how-to/how-to-introduction":{"id":"how-to/how-to-introduction","title":"TouchGFX \uc0ac\uc6a9 \ubc29\ubc95 \ube44\ub514\uc624","description":"\\"TouchGFX \uc0ac\uc6a9 \ubc29\ubc95\\" \ube44\ub514\uc624\ub294 TouchGFX Designer \ubc0f TouchGFX Engine \uae30\ub2a5\uc744 \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc548\ub0b4\ud569\ub2c8\ub2e4.","sidebar":"academy"},"how-to/images":{"id":"how-to/images","title":"\uc774\ubbf8\uc9c0 \ucd94\uac00","description":"\uc774 \ube44\ub514\uc624\ub97c \ud1b5\ud574 TouchGFX Designer\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubcf4\uc138\uc694. \uc774 \ube44\ub514\uc624\ub294 \uc774\ubbf8\uc9c0\ub97c \ud504\ub85c\uc81d\ud2b8\ub85c \uac00\uc838\uc624\ub294 \uac83\ubd80\ud130 \ub2e4\uc591\ud55c \uc774\ubbf8\uc9c0 \uc704\uc82f\uc744 \ud65c\uc6a9\ud558\uace0 \ub7f0\ud0c0\uc784\uc5d0\uc11c \uc774\ubbf8\uc9c0 \uc560\uc14b\uc744 \ubcc0\uacbd\ud558\ub294 \uac83\uc5d0 \uc774\ub974\ub294 \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ub2e4\ub8f9\ub2c8\ub2e4.","sidebar":"academy"},"how-to/install-touchgfx":{"id":"how-to/install-touchgfx","title":"TouchGFX \uc124\uce58","description":"STM32 \ub9c8\uc774\ud06c\ub85c\ucee8\ud2b8\ub864\ub7ec\uc6a9 GUI\ub97c \uc0dd\uc131\ud558\uace0 \uc2f6\uc9c0\ub9cc \uc5b4\ub5a4 \ud234\uc744 \uc0ac\uc6a9\ud574\uc57c \ud560\uc9c0 \ubaa8\ub974\uc2dc\uaca0\uc2b5\ub2c8\uae4c? \uc774 \ube44\ub514\uc624\ub97c \uc2dc\uccad\ud558\uc2ed\uc2dc\uc624!","sidebar":"academy"},"how-to/move-and-animate-widget":{"id":"how-to/move-and-animate-widget","title":"\uc704\uc82f\uc758 \uc774\ub3d9 \ubc0f \uc560\ub2c8\uba54\uc774\uc158 \uc801\uc6a9","description":"\uc704\uc82f\uc758 \uc774\ub3d9 \ubc0f \uc560\ub2c8\uba54\uc774\uc158 \uc801\uc6a9 \uae30\uc220\uc744 \uc644\ubcbd\ud788 \uc775\ud600 \uc0ac\uc6a9\uc790 \uc778\ud130\ud398\uc774\uc2a4\ub97c \ud5a5\uc0c1\uc2dc\ud0a4\ub294 \ubc95\uc744 \uc54c\uc544\ubcf4\uc2ed\uc2dc\uc624. \uc774 \ube44\ub514\uc624\ub294 TouchGFX\uc5d0\uc11c \uc704\uc82f\uc744 \uc774\ub3d9\ud558\uace0 \uc560\ub2c8\uba54\uc774\uc158\uc744 \uc801\uc6a9\ud558\ub294 \ub2e4\uc74c \uc138 \uac00\uc9c0 \uc811\uadfc \ubc29\uc2dd\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc2dc\uac01\uc801\uc73c\ub85c \uba4b\uc9c4 \uadf8\ub798\ud53d \uc0ac\uc6a9\uc790 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uc81c\uc791\ud558\ub294 \uacfc\uc815\uc744 \uc548\ub0b4\ud569\ub2c8\ub2e4.","sidebar":"academy"},"how-to/my-first-gui":{"id":"how-to/my-first-gui","title":"\ub0b4 \uccab GUI","description":"\uc774 \ube44\ub514\uc624\ub85c TouchGFX \uc5ec\uc815\uc744 \uc2dc\uc791\ud558\uc2ed\uc2dc\uc624! \ube44\ub514\uc624\ub97c \uc2dc\uccad\ud558\uace0 TouchGFX\ub97c \uc0ac\uc6a9\ud558\uc5ec \uac04\ub2e8\ud55c GUI\ub97c \uc0dd\uc131\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubcf4\uc2ed\uc2dc\uc624.","sidebar":"academy"},"how-to/save-flash-memory":{"id":"how-to/save-flash-memory","title":"\ud50c\ub798\uc2dc \uba54\ubaa8\ub9ac \uc808\uc57d","description":"\uc774 \\"TouchGFX \uc0ac\uc6a9 \ubc29\ubc95\\" \ube44\ub514\uc624\ub97c \ud1b5\ud574 TouchGFX GUI \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c \ud50c\ub798\uc2dc \uba54\ubaa8\ub9ac\uc758 \uc0ac\uc6a9\ub7c9\uc744 \uc904\uc774\ub294 \ube44\uacb0\uc744 \uc54c\uc544\ubcf4\uc2ed\uc2dc\uc624. \uc774 \ube44\ub514\uc624\uc5d0\uc11c\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \ub124 \uac00\uc9c0 \uc8fc\uc694 \uae30\ub2a5\uc5d0 \ub300\ud574 \uc790\uc138\ud788 \uc124\uba85\ud569\ub2c8\ub2e4.","sidebar":"academy"},"how-to/screen-transition":{"id":"how-to/screen-transition","title":"\uc2a4\ud06c\ub9b0 \uc804\ud658","description":"\ub9e4\ub044\ub7ec\uc6b4 \uc804\ud658\uc73c\ub85c TouchGFX GUI\uc5d0\uc11c\uc758 \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc744 \ud5a5\uc0c1\ud560 \uc218 \uc788\ub3c4\ub85d \uc2a4\ud06c\ub9b0 \uc804\ud658\uc5d0 \uad00\ud574 \uc790\uc138\ud788 \uc54c\uc544\ubcf4\uc138\uc694.","sidebar":"academy"},"how-to/single-framebuffer":{"id":"how-to/single-framebuffer","title":"\ub2e8\uc77c \ud504\ub808\uc784 \ubc84\ud37c\uc758 \uad6c\ud604","description":"\uc774 \ube44\ub514\uc624\uc5d0\uc11c\ub294 STM32U5G9J-DK2 \ubc0f NUCLEO-U575ZI + RVA35HI\uc5d0\uc11c \ub2e8\uc77c \ud504\ub808\uc784 \ubc84\ud37c \uc804\ub7b5\uc744 \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \ubc30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","sidebar":"academy"},"how-to/textarea":{"id":"how-to/textarea","title":"\ub7f0\ud0c0\uc784 \uc2dc \ud14d\uc2a4\ud2b8 \ubcc0\uacbd","description":"TextArea \ubc0f \uc640\uc77c\ub4dc\uce74\ub4dc\ub97c \uc774\uc6a9\ud574 \uc751\ub2f5\uc131\uc774 \uc6b0\uc218\ud55c GUI\ub97c \ub9cc\ub4e4\uc5b4 \ubcf4\uc138\uc694.","sidebar":"academy"},"tutorials/tutorial-01":{"id":"tutorials/tutorial-01","title":"Tutorial 1: Trying Out the Examples","description":"Follow this tutorial to learn the very basics of TouchGFX. You will see how to install TouchGFX and how to run the provided examples on TouchGFX Simulator and on an STM32 Evaluation Kit.","sidebar":"academy"},"tutorials/tutorial-02":{"id":"tutorials/tutorial-02","title":"Tutorial 2: Creating Your Own Application","description":"Follow this tutorial to learn more about the basics of TouchGFX. You will learn how to add images to your application and use buttons. You will also see how to use texts and calculated numbers. In the last steps you will write code to enhance the look of the UI you have created with TouchGFX Designer. This tutorial assumes no knowledge of TouchGFX, but we assume a little experience with programming.","sidebar":"academy"},"tutorials/tutorial-03":{"id":"tutorials/tutorial-03","title":"Tutorial 3: Applications with Multiple Screens","description":"In this tutorial, you will learn how to create multiple screens in an application and share data between the two screens. We will create an application that simulates a clock, which will use one screen to set hour and minute and pass the time to another screen which has a running clock.","sidebar":"academy"},"tutorials/tutorial-04":{"id":"tutorials/tutorial-04","title":"Tutorial 4: Creating a Scroll Wheel with Custom Behavior","description":"In this tutorial, you will learn how to create and configure the two widgets - Custom Container and Scroll Wheel. A Custom Container is a widget that enables you to create a new widget by combining multiple other widgets and add specific behavior for the widgets in the Custom Container. The Scroll Wheel is a widget used for creating a scrollable menu, consisting of multiple selectable items. The tutorial will also teach how user code can be created to change the behavior of a widget.","sidebar":"academy"},"tutorials/tutorial-05":{"id":"tutorials/tutorial-05","title":"Tutorial 5: Creating Custom Triggers and Actions","description":"With TouchGFX Designer it is possible to define your own interaction components with custom triggers and actions. Each Screen in your application can contain a collection of actions (these are simply void methods in C++) that you can call from within TouchGFX Designer as well as in code, while custom containers can also have a collection of triggers (which is equal to a callback in C++) which your application can react to.","sidebar":"academy"},"tutorials/tutorial-06/tutorial-06-introduction":{"id":"tutorials/tutorial-06/tutorial-06-introduction","title":"Tutorial 6: Using TextAreas","description":"In this tutorial, you will learn how to use TextAreas for more advanced usage. We will create an application that will show texts, in multiple languages and different typographies. We will also see how to change the appearance of our text and how to use wildcards through TouchGFX Designer and through code. To follow this tutorial more easily, we invite you to do tutorial 2 beforehand.","sidebar":"academy"},"tutorials/tutorial-06/tutorial-06-part-1":{"id":"tutorials/tutorial-06/tutorial-06-part-1","title":"Part 1 \u2013 Typography and Language","description":"In this first part of the tutorial 6, we will first see how to create new typography and then we will see how to change the language of our application.","sidebar":"academy"},"tutorials/tutorial-06/tutorial-06-part-2":{"id":"tutorials/tutorial-06/tutorial-06-part-2","title":"Part 2 \u2013 Appearance of TextArea and Wildcard","description":"To do this second part of tutorial 6, make sure you have done the first part. We will finish the implementation of the application started in the first part of the tutorial. First, we will see how to modify the textArea appearance and we will implement the \\"appearance\\" button. Then to finish we will implement the wildcards of the imformationTextArea.","sidebar":"academy"}}}')}}]);